    expect(result.stdout).toBe("trusted\n");
    expect(result.stderr).toBe("");
    expect(result.exitCode).toBe(0);
  });
});

import { execFileSync } from "node:child_process";
import { expect, it } from "vitest";

const tsxLoaderUrl = import.meta.resolve("tsx");
const defenseUrl = new URL("./defense-in-depth-box.ts", import.meta.url).href;
const bridgeUrl = new URL(
  "../commands/worker-bridge/bridge-handler.ts",
  import.meta.url,
).href;
const protocolUrl = new URL(
  "../commands/worker-bridge/protocol.ts",
  import.meta.url,
).href;
const filesystemUrl = new URL(
  "../fs/in-memory-fs/in-memory-fs.ts",
  import.meta.url,
).href;

function runSubprocess(body: string): string {
  return execFileSync(
    process.execPath,
    [
      "--import",
      tsxLoaderUrl,
      "--input-type=module",
      "--eval",
      `
      function deferred() {
        let resolve, reject;
        const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
        return { promise, resolve, reject };
      }
      ${body}
    `,
    ],
    { encoding: "utf8", timeout: 10_000 },
  );
}

// A subprocess makes an unhandled rejection fail the test by exiting Node.
it("handles a host tool rejection after the bridge is stopped", () => {
  expect(
    runSubprocess(`
      import assert from "node:assert/strict";
      import { setImmediate } from "node:timers/promises";
      import { DefenseInDepthBox } from ${JSON.stringify(defenseUrl)};
      import { BridgeHandler } from ${JSON.stringify(bridgeUrl)};
      import { createSharedBuffer, ProtocolBuffer, OpCode, Status } from ${JSON.stringify(protocolUrl)};
      import { InMemoryFs } from ${JSON.stringify(filesystemUrl)};

      const pending = deferred();
      const started = deferred();
      const shared = createSharedBuffer();
      const protocol = new ProtocolBuffer(shared);
      const bridge = new BridgeHandler(
        shared, new InMemoryFs(), "/", "test", undefined, 0, undefined,
        () => { started.resolve(); return pending.promise; },
      );
      protocol.setOpCode(OpCode.INVOKE_TOOL);
      protocol.setPath("test.read");
      protocol.setDataFromString("{}");
      protocol.setStatus(Status.READY);
      const handle = DefenseInDepthBox.getInstance(true).activate();
      let running;
      await handle.run(async () => { running = bridge.run(60_000); });
      await started.promise;
      await setImmediate();
      bridge.stop();
      handle.deactivate();
      pending.reject(new Error("late host failure"));
      assert.deepEqual(await running, { stdout: "", stderr: "", exitCode: 0 });
      assert.equal(protocol.getStatus(), Status.ERROR);
      assert.equal(protocol.getResultAsString(), "late host failure");
      await setImmediate();
      console.log("settled");
    `),
  ).toBe("settled\n");
});

import { describe, expect, it } from "vitest";
import { Bash } from "../Bash.js";
import { InMemoryFs } from "../fs/in-memory-fs/in-memory-fs.js";
import type { FsStat } from "../fs/interface.js";

class IdentitylessFs extends InMemoryFs {
  override async stat(path: string): Promise<FsStat> {
    const {
      identity: _identity,
      dev: _dev,
      ino: _ino,
      ...stat
    } = await super.stat(path);
    return stat;
  }
}

class NoRealpathFs extends InMemoryFs {
  override async realpath(_path: string): Promise<string> {
    throw new Error("ENOTSUP: realpath unavailable");
  }
}

describe("destructive command filesystem identity policy", () => {
  it.each([
    "cp",
    "mv",
  ])("%s permits an ordinary nonexistent file destination without realpath", async (command) => {
    const fs = new NoRealpathFs({ "/source": "content" });
    const bash = new Bash({ fs });

    const result = await bash.exec(`${command} /source /new`);

    expect(result.exitCode).toBe(0);
    expect(await fs.readFile("/new")).toBe("content");
  });

  it.each([
    "cp",
    "mv",
  ])("%s fails closed before replacing an existing file with unknown identity", async (command) => {
    const fs = new IdentitylessFs({
      "/source": "new",
      "/destination": "old",
    });
    const bash = new Bash({ fs });

    const result = await bash.exec(`${command} /source /destination`);

    expect(result.exitCode).toBe(1);
    expect(result.stderr).toContain("cannot safely determine");
    expect(await fs.readFile("/source")).toBe("new");
    expect(await fs.readFile("/destination")).toBe("old");
  });

  it.each([
    "cp -r",
    "mv",
  ])("%s fails closed when recursive containment cannot be canonicalized", async (command) => {
    const fs = new NoRealpathFs({ "/source/file": "content" });
    const bash = new Bash({ fs });

    const result = await bash.exec(`${command} /source /destination`);

    expect(result.exitCode).toBe(1);
    expect(result.stderr).toContain("cannot safely determine");
    expect(await fs.readFile("/source/file")).toBe("content");
    await expect(fs.stat("/destination")).rejects.toThrow("ENOENT");
  });
});

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { Bash } from "../Bash.js";
import { InMemoryFs } from "./in-memory-fs/in-memory-fs.js";
import type { IFileSystem } from "./interface.js";
import { OverlayFs } from "./overlay-fs/overlay-fs.js";
import { ReadWriteFs } from "./read-write-fs/read-write-fs.js";

const tempDirs: string[] = [];

afterEach(() => {
  for (const dir of tempDirs.splice(0)) {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

function realRoot(): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "just-bash-cycle-"));
  tempDirs.push(dir);
  return dir;
}

async function assertRejectsDescendantCopy(fsImpl: IFileSystem): Promise<void> {
  await fsImpl.writeFile("/src/file", "original");
  await expect(
    fsImpl.cp("/src", "/src/../src/child", { recursive: true }),
  ).rejects.toThrow("into itself");
  expect(await fsImpl.readFile("/src/file")).toBe("original");
  expect(await fsImpl.exists("/src/child")).toBe(false);
}

async function assertRejectsDescendantMove(fsImpl: IFileSystem): Promise<void> {
  await fsImpl.writeFile("/src/file", "original");
  await expect(fsImpl.mv("/src", "/src/child")).rejects.toThrow("into itself");
  expect(await fsImpl.readFile("/src/file")).toBe("original");
  expect(await fsImpl.exists("/src/child")).toBe(false);
}

describe("recursive copy and move cycle rejection", () => {
  it.each([
    ["InMemoryFs", () => new InMemoryFs()],
    ["OverlayFs", () => new OverlayFs({ root: realRoot(), mountPoint: "/" })],
    ["ReadWriteFs", () => new ReadWriteFs({ root: realRoot() })],
  ] as const)("rejects descendant copies atomically in %s", async (_name, create) => {
    await assertRejectsDescendantCopy(create());
  });

  it.each([
    ["InMemoryFs", () => new InMemoryFs()],
    ["OverlayFs", () => new OverlayFs({ root: realRoot(), mountPoint: "/" })],
    ["ReadWriteFs", () => new ReadWriteFs({ root: realRoot() })],
  ] as const)("rejects descendant moves atomically in %s", async (_name, create) => {
    await assertRejectsDescendantMove(create());
  });

  it("rejects command-level cp and mv before creating a destination", async () => {
    const bash = new Bash({ files: { "/src/file": "original" } });
    const copy = await bash.exec("cp -r /src /src/child");
    expect(copy.stdout).toBe("");
    expect(copy.stderr).toBe(
      "cp: cannot copy '/src' into itself, '/src/child'\n",
    );
    expect(copy.exitCode).toBe(1);

    const move = await bash.exec("mv /src /src/child");
    expect(move.stdout).toBe("");
    expect(move.stderr).toBe(
      "mv: cannot move '/src' into itself, '/src/child'\n",
    );
    expect(move.exitCode).toBe(1);
    expect(await bash.fs.readFile("/src/file")).toBe("original");
    expect(await bash.fs.exists("/src/child")).toBe(false);
  });
});

import { describe, expect, it } from "vitest";
import { Bash } from "../Bash.js";
import { printfCommand } from "../commands/printf/printf.js";
import { defineCommand } from "../custom-commands.js";
import { EMPTY_BYTES } from "../encoding.js";
import { resolveLimits } from "../limits.js";

describe("interpreter assignment gateway", () => {
  it("rejects special and positional names at the gateway itself", async () => {
    const assign = defineCommand(
      "assign-through-gateway",
      async (args, ctx) => {
        await ctx.assignShellVariable?.(args[0], "poison");
        return { stdout: "", stderr: "", exitCode: 0 };
      },
    );
    const bash = new Bash({ customCommands: [assign] });

    const positional = await bash.exec(
      "assign-through-gateway 1; printf '<%s>' \"$1\"",
    );
    const special = await bash.exec(
      "assign-through-gateway '#'; printf '<%s>' \"$#\"",
    );

    expect(positional.stdout).toBe("<>");
    expect(positional.stderr).toBe(
      "assign-through-gateway: 1: not a valid identifier\n",
    );
    expect(positional.exitCode).toBe(0);
    expect(special.stdout).toBe("<0>");
    expect(special.stderr).toBe(
      "assign-through-gateway: #: not a valid identifier\n",
    );
    expect(special.exitCode).toBe(0);
  });

  it("uses checked shell arithmetic for indexed printf subscripts", async () => {
    const bash = new Bash();
    const result = await bash.exec(
      "i=2; printf -v 'items[i+1]' value; printf '<%s>' \"${items[3]}\"",
    );

    expect(result.stdout).toBe("<value>");
    expect(result.stderr).toBe("");
    expect(result.exitCode).toBe(0);
  });

  it("follows namerefs and enforces readonly on the resolved target", async () => {
    const bash = new Bash();
    const assigned = await bash.exec(
      'target=old; declare -n ref=target; printf -v ref new; echo "$target"',
    );
    const readonly = await bash.exec(
      'target=old; readonly target; declare -n ref=target; printf -v ref new; echo "$target"',
    );

    expect(assigned.stdout).toBe("new\n");
    expect(assigned.stderr).toBe("");
    expect(assigned.exitCode).toBe(0);
    expect(readonly.stdout).toBe("old\n");
    expect(readonly.stderr).toBe("printf: target: readonly variable\n");
    expect(readonly.exitCode).toBe(0);
  });

  it("fails clearly for array assignment in a bare embedder context", async () => {
    const env = new Map<string, string>();
    const result = await printfCommand.execute(["-v", "items[0]", "value"], {
      fs: {} as never,
      cwd: "/",
      env,
      stdin: EMPTY_BYTES,
      limits: resolveLimits(),
    });

    expect(result.stdout).toBe("");
    expect(result.stderr).toBe(
      "printf: printf -v array assignment requires an interpreter assignment gateway\n",
    );
    expect(result.exitCode).toBe(1);
    expect(Array.from(env.entries())).toEqual([]);
  });
});

import { describe, expect, it } from "vitest";
import { sanitizeUnknownError, wrapWasmCallback } from "./wasm-callback.js";

describe("wrapWasmCallback", () => {
  it("passes through callback return values", () => {
    const callback = wrapWasmCallback(
      "python3-worker",
      "print",
      (text: string) => text.toUpperCase(),
    );

    expect(callback("ok")).toBe("OK");
  });

  it("throws sanitized callback errors", () => {
    const callback = wrapWasmCallback("python3-worker", "printErr", () => {
      throw new Error(
        "boom at /Users/attacker/private.txt via node:internal/modules/cjs/loader:1234",
      );
    });

    expect(() => callback()).toThrow(
      "python3-worker printErr callback failed: boom at <path> via <internal>:1234",
    );
  });

  it("sanitizes unknown thrown values", () => {
    expect(
      sanitizeUnknownError(
        "bad at /Users/attacker/home with node:internal/test",
      ),
    ).toBe("bad at <path> with <internal>");
  });
});
